/**
 * The Library: an independent peptide reference built from the app catalog.
 *
 * Data comes from `data/library-peptides.json`, generated by
 * `scripts/build-library-data.mjs` out of the iOS catalog. Never hand-edit the
 * JSON, re-run the generator.
 *
 * Route shape (one hub + one page per chapter, so each long-tail query gets its
 * own indexable target):
 *
 *   /library
 *   /library/all-peptides
 *   /library/<category>
 *   /library/<category>/<peptide>
 *   /library/<category>/<peptide>/<chapter>
 */
import PEPTIDE_DATA from "./data/library-peptides.json";

/**
 * Dashes to commas, for body prose.
 *
 * Different job from `normalizeDashes`. That one splits a display string into
 * two sentences, which is right for a takeaway but wrong mid-paragraph: the
 * catalog uses PAIRED dashes as parentheses ("gastric stability—surviving
 * extreme pH—distinguishes it"), and splitting those leaves two fragments.
 * A comma reads correctly in both the paired and the single case.
 *
 * En dashes are only converted when spaced. An unspaced one is a numeric range
 * ("250–500 mcg", "2–8°C") and turning that into "250, 500" would change what
 * the page says.
 */
export function dashesToCommas(text: string): string {
  return text
    // Em dash, unless it sits between two digits.
    .replace(/(\d)\s*—\s*(\d)/g, "$1-$2")
    .replace(/\s*—\s*/g, ", ")
    // Spaced en dash only.
    .replace(/\s+–\s+/g, ", ")
    // A dash next to punctuation leaves doubles behind.
    .replace(/,\s*,/g, ",")
    .replace(/\s+,/g, ",")
    .replace(/,\s*([.;:!?])/g, "$1")
    .replace(/\s{2,}/g, " ");
}


export type CategorySlug =
  | "weight-loss"
  | "recovery"
  | "performance"
  | "longevity"
  | "aesthetics"
  | "cognitive";

export type Tier = "S" | "A" | "B" | "C" | "D" | "F";

export interface QuickFact {
  key: string;
  value: string;
}
export interface EvidenceClaim {
  claim: string;
  tier: string;
  note?: string;
}
export interface Trial {
  name: string;
  date?: string;
  journal?: string;
  headlineStat?: string;
}
export interface Source {
  url: string;
  title: string;
  type?: string;
  authors?: string[];
  year?: number;
}
export interface PkPoint {
  label: string;
  value: number;
}
export interface PkChart {
  title: string;
  unit: string;
  halfLifeLabel: string;
  routeLabel?: string;
  points: PkPoint[];
}
export interface ChapterSection {
  subheader: string;
  body: string;
  caption: string | null;
  pkChart: PkChart | null;
}
export interface Chapter {
  key: string;
  title: string;
  sections: ChapterSection[];
}

export interface Peptide {
  slug: string;
  name: string;
  category: CategorySlug;
  sectionLabel: string;
  sectionIcon: string | null;
  topics: string[];
  subtitle: string;
  description: string;
  researchTier: Tier | null;
  isFeatured: boolean;
  standardDose: { low?: number; high?: number; unit?: string; frequency?: string } | null;
  doseCard: { primary?: string; frequency?: string } | null;
  reconstitution: { vialMg?: number; recommendedBacMl?: number; notes?: string } | null;
  halfLife: string | null;
  route: string[];
  commonStacks: string[];
  contraindications: string[];
  quickFacts: QuickFact[];
  evidenceSummary: string[];
  evidenceClaims: EvidenceClaim[];
  researchHeadlines: { lede: string; body: string; tier?: string }[];
  trials: Trial[];
  sources: Source[];
  chapters: Chapter[];
  readMinutes: number;
  publishedAt: string | null;
  updatedAt: string | null;
}

/**
 * The catalog, with dashes normalised once at load.
 *
 * Doing this per component missed every surface that renders a catalog string
 * without going through `Prose`: card subtitles, composed FAQ answers, search
 * blurbs, meta descriptions, JSON-LD, the OG images, and `/llms.txt`. Cleaning
 * the data instead means there is exactly one place to get it right, and no
 * new consumer can reintroduce one.
 *
 * Runs at module load, which on this site is build time — every library route
 * is statically generated.
 */
function cleanPeptide(p: Peptide): Peptide {
  return {
    ...p,
    subtitle: dashesToCommas(p.subtitle),
    description: dashesToCommas(p.description),
    halfLife: p.halfLife ? dashesToCommas(p.halfLife) : p.halfLife,
    contraindications: p.contraindications.map(dashesToCommas),
    reconstitution: p.reconstitution
      ? {
          ...p.reconstitution,
          notes: p.reconstitution.notes ? dashesToCommas(p.reconstitution.notes) : p.reconstitution.notes,
        }
      : p.reconstitution,
    doseCard: p.doseCard
      ? {
          ...p.doseCard,
          primary: p.doseCard.primary ? dashesToCommas(p.doseCard.primary) : p.doseCard.primary,
          frequency: p.doseCard.frequency ? dashesToCommas(p.doseCard.frequency) : p.doseCard.frequency,
        }
      : p.doseCard,
    sources: p.sources.map((src) => ({ ...src, title: dashesToCommas(src.title) })),
    researchHeadlines: p.researchHeadlines.map((h) => ({
      ...h,
      lede: dashesToCommas(h.lede),
      body: dashesToCommas(h.body),
    })),
    evidenceSummary: p.evidenceSummary.map(dashesToCommas),
    evidenceClaims: p.evidenceClaims.map((c) => ({
      ...c,
      note: c.note ? dashesToCommas(c.note) : c.note,
    })),
    quickFacts: p.quickFacts.map((f) => ({ ...f, value: dashesToCommas(f.value) })),
    trials: p.trials.map((t) => ({
      ...t,
      headlineStat: t.headlineStat ? dashesToCommas(t.headlineStat) : t.headlineStat,
    })),
    chapters: p.chapters.map((ch) => ({
      ...ch,
      sections: ch.sections.map((sec) => ({ ...sec, body: dashesToCommas(sec.body) })),
    })),
  };
}

export const PEPTIDES = (PEPTIDE_DATA as unknown as Peptide[]).map(cleanPeptide);

/* ---- Category identity ---------------------------------------------------
   Ported from the app: `LibraryModels.swift` maps a section label to one of
   five brand ramps (`String.asCategoryGradient`) and the catalog carries an SF
   Symbol per section (`sectionIcon`). The web repeats both mappings so a
   compound reads the same on both surfaces. Two categories legitimately share
   the green ramp, exactly as they do in the app — the icon and the label are
   what separate them, colour is never the only signal. */

export type Ramp = "warm" | "cool" | "green" | "brown" | "gold";
/** `String.asCategoryGradient`, keyed by the app's own section labels. */
const RAMP_BY_SECTION: Record<string, Ramp> = {
  "fat loss & metabolism": "warm",
  "recovery & healing": "cool",
  "recovery & wellness": "cool",
  "growth & GH": "green",
  "growth & hormones": "green",
  "growth & performance": "green",
  "longevity & healthspan": "green",
  "longevity & brain": "brown",
  "focus & cognition": "brown",
  "sexual health": "brown",
  "skin & aesthetics": "gold",
};

export type IconKey =
  | "flame"
  | "bandage"
  | "leaf"
  | "dumbbell"
  | "infinity"
  | "sparkles"
  | "brain"
  | "heart";

/** The catalog's SF Symbol names, resolved to this site's icon set. */
const ICON_BY_SYMBOL: Record<string, IconKey> = {
  "flame.fill": "flame",
  "bandage.fill": "bandage",
  "leaf.fill": "leaf",
  "figure.strengthtraining.traditional": "dumbbell",
  infinity: "infinity",
  sparkles: "sparkles",
  "brain.head.profile": "brain",
  "heart.fill": "heart",
};

export function rampFor(p: Peptide): Ramp {
  return RAMP_BY_SECTION[p.sectionLabel] ?? "warm";
}

/** The compound's own mark, falling back to its category's. */
export function iconFor(p: Peptide): IconKey {
  const mapped = p.sectionIcon ? ICON_BY_SYMBOL[p.sectionIcon] : undefined;
  return mapped ?? categoryBySlug(p.category)?.icon ?? "flame";
}

